/**
 * Community API - 交流社区接口
 * 
 * 接口列表:
 * - getPosts: 获取所有帖子 (支持筛选)
 * - getPostDetail: 获取单个帖子详情
 * - createPost: 创建新帖子
 * - getCategories: 获取社区分类
 */

import request from './request.js'

export default {
  /**
   * 获取所有帖子
   * @param {object} params - 查询参数 { category, sort, page, limit }
   */
  getPosts(params = {}) {
    return request.get('/community', { params })
  },

  /**
   * 获取单个帖子详情
   * @param {string} id - 帖子ID
   */
  getPostDetail(id) {
    return request.get(`/community/${id}`)
  },

  /**
   * 创建新帖子
   * @param {object} data - 帖子数据 { title, content, category, images }
   */
  createPost(data) {
    return request.post('/community', data)
  },

  /**
   * 获取社区分类
   */
  getCategories() {
    return request.get('/community/categories')
  }
}
